@php
  $campusResourceCatalog = $enterprisePresentation['locations'] ?? app(\App\Enterprise\LocationCatalog::class)->all();
  $campusOfficialSource = 'https://www.lmc.edu/campus-life/campus-safety/campus-operations/files/campus-parking-map.pdf';
  $campusOfficialPlan = ($campusResourceCatalog['catalog'] ?? '') === 'lees-mcrae-official-map-v1'
    || collect($campusResourceCatalog['entries'] ?? [])->contains(fn ($entry) =>
      ($entry['source_url'] ?? $campusResourceCatalog['source_url'] ?? null) === $campusOfficialSource
      && (string) ($entry['source_page'] ?? $campusResourceCatalog['source_page'] ?? '') === '2');
@endphp
